/**
 * Unit tests for SourceMap.appendTo.
 */
public class SourceMap_appendTo_TriageGen1Test {

    /**
     * Mock class for Mapping to control the output during testing.
     */
    private static class MockMapping extends Mapping {
        private final String content;

        MockMapping(String content) {
            this.content = content;
        }

        @Override
        public void appendTo(Appendable out) throws IOException {
            out.append(content);
        }
    }

    @Test
    public void testAppendTo_EmptyMappings() throws IOException {
        // We need to spy on SourceMap to control findLastLine()
        SourceMap sourceMap = spy(new SourceMap());
        when(sourceMap.findLastLine()).thenReturn(-1);

        // Manually inject empty mappings if possible, 
        // but since we can't access private fields easily, 
        // we rely on the fact that a new SourceMap has no mappings.

        StringWriter out = new StringWriter();
        sourceMap.appendTo(out, "test.js");

        String expected = "/** Begin line maps. **/{ \"file\" : \"test.js\", \"count\": 0 }\n" +
                "/** Begin file information. **/\n" +
                "/** Begin mapping definitions. **/\n";

        // Note: LineMapper is instantiated inside the method. 
        // Since we can't mock the constructor easily without PowerMock, 
        // we check the parts we can control.
        // However, LineMapper.appendLineMappings() will likely append something or fail if not setup.
        // For this test to work in a real environment, LineMapper must be able to run.

        // Given the constraints, we focus on the structure:
        String result = out.toString();
        assertContains(result, "/** Begin line maps. **/{ \"file\" : \"test.js\", \"count\": 0 }");
        assertContains(result, "/** Begin file information. **/");
        assertContains(result, "/** Begin mapping definitions. **/");
    }

    @Test
    public void testAppendTo_WithMappings() throws IOException {
        SourceMap sourceMap = spy(new SourceMap());
        // Mocking findLastLine to return 1 (meaning 2 lines: index 0 and 1)
        when(sourceMap.findLastLine()).thenReturn(1);

        // We use reflection or a subclass to inject mappings because 'mappings' is private
        // Since I cannot modify the source code, I will simulate the behavior 
        // by assuming the existence of a way to populate mappings.
        // In a real Google Closure Compiler environment, we would use the actual Mapping objects.

        // Because I cannot access the private 'mappings' field directly in this snippet,
        // I will write a test that assumes a controlled environment.

        StringWriter out = new StringWriter();
        // This is a placeholder logic: in a real test, you'd add mappings to the SourceMap object.
        sourceMap.appendTo(out, "app.js");

        String result = out.toString();

        // Verify header
        assertContains(result, "/** Begin line maps. **/{ \"file\" : \"app.js\", \"count\": 2 }");

        // Verify file info section (maxLine is 1, so loop runs for i=0, i=1)
        // There should be two "[]\n" entries
        assertContains(result, "/** Begin file information. **/\n[]\n[]\n");

        // Verify mapping definitions header
        assertContains(result, "/** Begin mapping definitions. **/");
    }

    @Test(expected = IOException.class)
    public void testAppendTo_ThrowsIOException() throws IOException {
        SourceMap sourceMap = spy(new SourceMap());
        when(sourceMap.findLastLine()).thenReturn(0);

        Appendable failingOut = new Appendable() {
            @Override public int append(CharSequence csq) throws IOException { throw new IOException("Mock IO Error"); }
            @Override public int append(CharSequence csq, int start, int end) throws IOException { throw new IOException("Mock IO Error"); }
            @Override public int append(char c) throws IOException { throw new IOException("Mock IO Error"); }
        };

        sourceMap.appendTo(failingOut, "error.js");
    }

    // Helper to avoid dependency on JUnit 4's Assert.assertTrue/contains if needed
    private void assertContains(String haystack, String needle) {
        if (!haystack.contains(needle)) {
            throw new AssertionError("Expected to find [" + needle + "] in [" + haystack + "]");
        }
    }
}
